from pathlib import Path
import json
code=r'''using System;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;public static class Probe100{public static string Run(){var b=new StringBuilder();var a=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Items/Fence.prefab");b.AppendLine("Fence root rot="+a.transform.localEulerAngles);var wood=GameObject.Find("Lobby_Island_Visual_Prototype").transform.Find("04_Boat_Skins_Showcase/Wooden_Castle_Boat_Showcase100/Actual_Castle_Wooden_Boat_Static100");foreach(var f in wood.GetComponentsInChildren<MeshFilter>()){var v=f.sharedMesh.vertices.Select(f.transform.TransformPoint).Select(wood.parent.InverseTransformPoint).ToArray();if(v.Min(q=>q.z)<-8.4f||v.Max(q=>q.z)>8.4f)b.AppendLine(f.name+" parent="+f.transform.parent.name+" minZ="+v.Min(q=>q.z)+" maxZ="+v.Max(q=>q.z));}System.IO.File.WriteAllText("Library/WorkshopBackups/DB-ON-100/probe.txt",b.ToString());return b.ToString();}}'''
Path('Library/WorkshopBackups/DB-ON-100/probe.json').write_text(json.dumps({'csharpCode':code,'className':'Probe100','methodName':'Run'}),encoding='utf-8')
